const rawInput = $input.first().json;
// JSearch v2 me array 'data.jobs' ke andar hai
const jobs = (rawInput.data && rawInput.data.jobs) ? rawInput.data.jobs : [];

// 1. Aapki Target Companies
const targetCompanies = [
  'deloitte', 'hcl', 'samsung', 'salesforce', 'google', 'microsoft', 
  'amazon', 'oracle', 'cisco', 'adobe', 'walmart', 'intuit', 'flipkart', 
  'uber', 'servicenow', 'atlassian', 'target', 'paypal', 'vmware', 'accenture'
];

// 2. Aapke Target Roles / Keywords
const targetKeywords = [
  'devops', 'platform', 'linux', 'gcp', 'azure', 'aks', 'kubernetes', 'sre', 'cloud'
];

let tableRows = '';
let matchedCount = 0;

for (const data of jobs) {
  const rawTitle = data.job_title || data.title || 'DevOps Opening';
  const rawCompany = data.employer_name || data.organization || data.company || 'Tech Company';
  const url = data.job_apply_link || data.url || '#';
  const location = data.job_city ? `${data.job_city}, ${data.job_country || ''}` : (data.job_country || 'India / Remote');

  const titleLower = rawTitle.toLowerCase();
  const companyLower = rawCompany.toLowerCase();

  const matchesKeyword = targetKeywords.some(k => titleLower.includes(k));
  const matchesCompany = targetCompanies.some(c => companyLower.includes(c));

  if (matchesKeyword || matchesCompany) {
    matchedCount++;
    tableRows += `
      <tr style="border-bottom: 1px solid #e0e0e0;">
        <td style="padding: 12px 10px;">
          <a href="${url}" target="_blank" style="color: #0a66c2; font-weight: 600; text-decoration: none;">
            ${rawTitle}
          </a>
        </td>
        <td style="padding: 12px 10px; font-weight: 500; color: #333;">${rawCompany}</td>
        <td style="padding: 12px 10px; color: #666;">${location}</td>
      </tr>
    `;
  }
}

if (matchedCount === 0) {
  tableRows = `<tr><td colspan="3" style="padding: 15px; text-align: center; color: #777;">No matching jobs found for selected filters.</td></tr>`;
}

const emailHtml = `
  <div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; max-width: 700px; margin: auto; padding: 20px; border: 1px solid #eee; border-radius: 8px;">
    <h2 style="color: #0a66c2; margin-top: 0;">🚀 DevOps, Cloud & Product Companies Alert</h2>
    <p style="color: #555; font-size: 14px;">Filtered jobs from top product companies and target cloud roles:</p>
    <table style="width: 100%; border-collapse: collapse; text-align: left; font-size: 14px;">
      <thead>
        <tr style="background-color: #f8f9fa; border-bottom: 2px solid #dee2e6;">
          <th style="padding: 10px;">Role / Title</th>
          <th style="padding: 10px;">Company</th>
          <th style="padding: 10px;">Location</th>
        </tr>
      </thead>
      <tbody>
        ${tableRows}
      </tbody>
    </table>
  </div>
`;

return [{ json: { emailHtml, matchedCount } }];
